(* [comment removed for export] *)
Lemma acc_after_stack : forall l h m mx a n, accessible m a n -> munch [(l, h)]%Z m mx -> aceil <= l -> accessible mx a n.
Proof.
  intros l h m mx a n AC MU Hl. eapply accessible_transport_hi; [exact AC| exact MU|].
  pose proof aceil_facts as (AF & _). constructor; [right; cbn; unfold AHI_LO; lia| constructor].
Qed.

(* [comment removed for export] *)
Definition oloc (D n : Z) : Prop := aapp D n \/ aceil <= D.
Lemma oloc_win : forall D n l h, oloc D n -> D <= l -> h <= D + n -> (AIMG_TOP <= l /\ h <= ALOWSH_LO) \/ AHI_LO <= l.
Proof.
  intros D n l h [[[P1 P2]|[P1 P2]]|P] H1 H2; [left; lia| right; lia|]. pose proof aceil_facts as (AF & _). right. unfold AHI_LO. lia.
Qed.
Lemma acc_after : forall W m mx a n, accessible m a n -> munch W m mx -> wins_hi W -> accessible mx a n.
Proof. intros. eapply accessible_transport_hi; eauto. Qed.

