(* [comment removed for export] *)
Definition anyex_fn_query_ctx_post (ra sp gp tp s0 s1 a0 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (R ioc lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a1 a2 a3 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(lo, bv_unsigned sp); (R, R + 8)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp)
    /\ rw_cells asegs m' R [C8 (wz ioc)].

Definition anyex_fn_query_ctx_stmt : Prop :=
  forall (R S ioc lo : Z) ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (rj : list byte),
  ro_cells asegs m S [C8 (wz ioc)] ->
  rw_cells asegs m R [CB 8 rj] ->
  (S + 8 <= R \/ R + 8 <= S) -> 0 <= ioc < 2^64 -> ioc mod 4 = 0 ->
  mem_inv asegs m ->
  (* [comment removed for export] *)
  stk asegs m lo (bv_unsigned sp) -> lo + ANYEX_FN_STACK <= bv_unsigned sp -> aceil <= lo ->
  (bv_unsigned sp <= S \/ S + 8 <= lo) -> (bv_unsigned sp <= R \/ R + 8 <= lo) ->
  bv_unsigned ra mod 2 = 0 ->
  ACONST m -> accessible m S 8 -> S mod 8 = 0 -> accessible m R 8 -> R mod 8 = 0 ->
  evt asegs (anyex_fn_query_ctx_post ra sp gp tp s0 s1 (wz R) a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 F fc R ioc lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz R) (wz S) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_ANYEX_FN_QUERY_CTX) fc None m (seg_rom asegs)).

